global.ReplayEngine.registerScene({"id":"MT_CYCLISTS_ROUNDABOUT_ANY_DIRECTION_V1","category":"cyclists","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"cyclistsRoundaboutAnyDirection","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Cyclists at a roundabout: expect any direction","accessibilityLabel":"Real roundabout with cyclists and moving traffic in the same junction environment","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/13361172/","videoSources":["https://www.pexels.com/download/video/13361172/"],"poster":"https://images.pexels.com/videos/13361172/pexels-photo-13361172.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · FÁBIO REIS DE ABREU (PORTUGA)","sourcePage":"https://www.pexels.com/video/square-in-roundabout-in-city-13361172/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Tre ciclisti si avvicinano alla rotatoria restando sulla sinistra.","textEn":"Three cyclists approach the roundabout while keeping to the left."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"La posizione a sinistra non ti dice con certezza quale uscita prenderanno.","textEn":"Their left-hand position does not tell you for certain which exit they will take."},{"at":4.5,"end":6.8,"event":"explain","textIt":"I ciclisti possono mantenere la sinistra per sicurezza anche se proseguono oltre.","textEn":"Cyclists may keep left for safety even when continuing farther around."},{"at":6.9,"end":10,"event":"correct","textIt":"Aspettati che possano andare in qualsiasi direzione e lascia spazio.","textEn":"Expect them to go in any direction and give them room."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["cyclistsRoundaboutAnyDirection_p0","cyclistsRoundaboutAnyDirection_p1","cyclistsRoundaboutAnyDirection_p2"],"hotspot":{"left":50,"top":48,"radiusX":42,"radiusY":34,"instructionIt":"TOCCA I CICLISTI","instructionEn":"TAP THE CYCLISTS","ariaIt":"Tocca i ciclisti nella rotatoria","ariaEn":"Tap the cyclists at the roundabout"},"phases":[{},{"titleIt":"CICLISTI A SINISTRA","titleEn":"CYCLISTS KEEPING LEFT","bodyIt":"Possono restare sulla sinistra per proteggere il proprio spazio.","bodyEn":"They may keep left to protect their road space."},{"titleIt":"NON PRESUMERE L’USCITA","titleEn":"DO NOT ASSUME THE EXIT","bodyIt":"La posizione non significa che svolteranno necessariamente a sinistra.","bodyEn":"Their position does not mean they will necessarily turn left."},{"titleIt":"QUALSIASI DIREZIONE","titleEn":"ANY DIRECTION","bodyIt":"Aspettati qualunque uscita e mantieni distanza.","bodyEn":"Expect any exit and maintain space."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Non dedurre la direzione solo dalla corsia: pensa alla sicurezza dei ciclisti.","missEn":"Do not infer their direction from the lane alone: think about cyclist safety.","hitIt":"Esatto: possono andare in qualsiasi direzione.","hitEn":"Correct: they may go in any direction."},"learning":{"correctIt":"In rotatoria i ciclisti possono restare a sinistra anche se prendono altre uscite.","correctEn":"At a roundabout cyclists may keep left even when taking other exits."}});

