global.ReplayEngine.registerScene({"id":"MT_POLICE_FOLLOWING_STOP_SIGNAL_V1","category":"police-signals","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"policeFollowingStopSignal","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Police behind you: recognise the stop signal","accessibilityLabel":"Real police car with clearly flashing emergency lights in an urban road setting","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/7714377/","videoSources":["https://www.pexels.com/download/video/7714377/"],"poster":"https://images.pexels.com/videos/7714377/pexels-photo-7714377.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Kindel Media","sourcePage":"https://www.pexels.com/video/video-of-a-police-car-7714377/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Un’auto della polizia ti segue e attiva segnali luminosi chiari.","textEn":"A police car follows you and activates clear light signals."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Devi riconoscere subito che gli agenti vogliono attirare la tua attenzione.","textEn":"You must quickly recognise that the officers want your attention."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Lampeggio dei fari e luci blu sono segnali chiari della polizia.","textEn":"Flashing headlights and blue lights are clear police signals."},{"at":6.9,"end":10,"event":"correct","textIt":"Segui le indicazioni e fermati in sicurezza appena possibile.","textEn":"Follow the instruction and stop safely as soon as possible."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["policeFollowingStopSignal_p0","policeFollowingStopSignal_p1","policeFollowingStopSignal_p2"],"hotspot":{"left":50,"top":48,"radiusX":38,"radiusY":34,"instructionIt":"TOCCA LE LUCI BLU","instructionEn":"TAP THE BLUE LIGHTS","ariaIt":"Tocca le luci di emergenza della polizia","ariaEn":"Tap the police emergency lights"},"phases":[{},{"titleIt":"POLIZIA DIETRO","titleEn":"POLICE BEHIND","bodyIt":"Controlla i segnali del veicolo che ti segue.","bodyEn":"Check the signals from the vehicle following you."},{"titleIt":"SEGNALI CHIARI","titleEn":"CLEAR SIGNALS","bodyIt":"Lampeggio e luci blu indicano che devi prestare attenzione.","bodyEn":"Flashing headlights and blue lights tell you to pay attention."},{"titleIt":"FERMATI IN SICUREZZA","titleEn":"STOP SAFELY","bodyIt":"Accosta e fermati appena puoi farlo senza creare pericolo.","bodyEn":"Pull over and stop as soon as you can do so safely."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Cerca il segnale luminoso tipico di un veicolo della polizia.","missEn":"Look for the typical light signal from a police vehicle.","hitIt":"Esatto: lampeggio e luci blu sono segnali chiari.","hitEn":"Correct: flashing headlights and blue lights are clear signals."},"learning":{"correctIt":"Se la polizia ti segnala di fermarti, riconosci i segnali chiari e fermati in sicurezza.","correctEn":"If police signal you to stop, recognise the clear signals and stop safely."}});

global.ReplayEngine.registerScene({"id":"MT_HANDS_FREE_PHONE_STILL_DISTRACTS_V1","category":"mobile-phones","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"handsFreePhoneStillDistracts","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Hands-free driving calls still divert attention","accessibilityLabel":"Real driver inside a vehicle interacting with phone technology while at the wheel","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/7362574/","videoSources":["https://www.pexels.com/download/video/7362574/"],"poster":"https://images.pexels.com/videos/7362574/pexels-photo-7362574.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · RDNE Stock project","sourcePage":"https://www.pexels.com/video/woman-using-a-cellphone-inside-the-vehicle-7362574/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Il conducente usa una funzione telefonica mentre è al posto di guida.","textEn":"The driver uses phone technology while at the wheel."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Anche senza tenere il telefono in mano, la conversazione impegna la mente.","textEn":"Even without holding the phone, the conversation occupies mental attention."},{"at":4.5,"end":6.8,"event":"explain","textIt":"La distrazione mentale riduce l’attenzione disponibile per la strada.","textEn":"Mental distraction reduces the attention available for the road."},{"at":6.9,"end":10,"event":"correct","textIt":"Il vivavoce può comunque distogliere la tua attenzione.","textEn":"Hands-free use can still divert your attention."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["handsFreePhoneStillDistracts_p0","handsFreePhoneStillDistracts_p1","handsFreePhoneStillDistracts_p2"],"hotspot":{"left":51,"top":47,"radiusX":34,"radiusY":38,"instructionIt":"TOCCA IL CONDUCENTE","instructionEn":"TAP THE DRIVER","ariaIt":"Tocca il conducente impegnato nella chiamata","ariaEn":"Tap the driver engaged with the call"},"phases":[{},{"titleIt":"CHIAMATA VIVAVOCE","titleEn":"HANDS-FREE CALL","bodyIt":"Le mani possono restare sul volante, ma la mente è impegnata.","bodyEn":"Your hands may remain on the wheel, but your mind is occupied."},{"titleIt":"DISTRAZIONE MENTALE","titleEn":"MENTAL DISTRACTION","bodyIt":"Una parte dell’attenzione viene sottratta alla guida.","bodyEn":"Part of your attention is taken away from driving."},{"titleIt":"ATTENZIONE RIDOTTA","titleEn":"REDUCED ATTENTION","bodyIt":"Il vivavoce non elimina il rischio di distrazione.","bodyEn":"Hands-free use does not remove the distraction risk."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Non pensare solo alle mani: considera anche dove è concentrata la mente.","missEn":"Do not think only about the hands: consider where the mind is focused.","hitIt":"Esatto: anche il vivavoce può distogliere l’attenzione.","hitEn":"Correct: even hands-free use can divert attention."},"learning":{"correctIt":"Le chiamate in vivavoce creano comunque distrazione mentale durante la guida.","correctEn":"Hands-free calls still create mental distraction while driving."}});

global.ReplayEngine.registerScene({"id":"MT_RIGHT_TURN_CHECK_OVERTAKING_MOTORCYCLIST_V1","category":"motorcyclists","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"rightTurnCheckOvertakingMotorcyclist","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Before turning right: check for overtaking motorcyclists","accessibilityLabel":"Real traffic footage with motorcycles overtaking among cars and larger vehicles","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/16385740/","videoSources":["https://www.pexels.com/download/video/16385740/"],"poster":"https://images.pexels.com/videos/16385740/pexels-photo-16385740.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Wallpapers Hub","sourcePage":"https://www.pexels.com/video/driving-on-a-highway-with-heavy-traffic-16385740/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Prima di girare a destra controlla cosa sta arrivando sul tuo lato destro.","textEn":"Before turning right, check what is approaching on your right side."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Un motociclista può avanzare rapidamente accanto alle auto ed entrare nel punto cieco.","textEn":"A motorcyclist can move quickly alongside cars and enter your blind spot."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Se inizi la svolta senza controllare, puoi tagliargli la traiettoria.","textEn":"If you begin the turn without checking, you may cut across the rider’s path."},{"at":6.9,"end":10,"event":"correct","textIt":"Controlla i motociclisti che potrebbero sorpassarti sulla destra.","textEn":"Check for motorcyclists who may be overtaking on your right."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["rightTurnCheckOvertakingMotorcyclist_p0","rightTurnCheckOvertakingMotorcyclist_p1","rightTurnCheckOvertakingMotorcyclist_p2"],"hotspot":{"left":54,"top":55,"radiusX":40,"radiusY":36,"instructionIt":"TOCCA IL MOTOCICLISTA","instructionEn":"TAP THE MOTORCYCLIST","ariaIt":"Tocca il motociclista che può avanzare sulla destra","ariaEn":"Tap the motorcyclist who may be overtaking on the right"},"phases":[{},{"titleIt":"PRIMA DELLA SVOLTA","titleEn":"BEFORE THE TURN","bodyIt":"Controlla specchi e lato destro immediatamente prima della manovra.","bodyEn":"Check mirrors and the right side immediately before the manoeuvre."},{"titleIt":"MOTO IN SORPASSO","titleEn":"OVERTAKING MOTORCYCLE","bodyIt":"Una moto può comparire rapidamente accanto al veicolo.","bodyEn":"A motorcycle can quickly appear alongside your vehicle."},{"titleIt":"NON TAGLIARE LA TRAIETTORIA","titleEn":"DO NOT CUT ACROSS","bodyIt":"Aspetta finché sei certo che il lato destro sia libero.","bodyEn":"Wait until you are certain the right side is clear."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Pensa a chi può avanzare velocemente nello spazio alla tua destra.","missEn":"Think about who may move quickly through the space on your right.","hitIt":"Esatto: controlla i motociclisti che potrebbero sorpassarti sulla destra.","hitEn":"Correct: check for motorcyclists who may be overtaking on your right."},"learning":{"correctIt":"Subito prima di svoltare a destra controlla motociclisti che potrebbero essere in sorpasso sul tuo lato destro.","correctEn":"Just before turning right, check for motorcyclists who may be overtaking on your right."}});

global.ReplayEngine.registerScene({"id":"MT_LARGE_VEHICLE_HIDES_OVERTAKER_V1","category":"large-vehicles","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"largeVehicleHidesOvertaker","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Large vehicle from the right: it may hide an overtaking vehicle","accessibilityLabel":"Real traffic footage showing a car overtaking alongside a large transport truck","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/5266052/","videoSources":["https://www.pexels.com/download/video/5266052/"],"poster":"https://images.pexels.com/videos/5266052/pexels-photo-5266052.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Get Lost Mike","sourcePage":"https://www.pexels.com/video/car-over-taking-a-transport-truck-on-expressway-5266052/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Un veicolo grande si avvicina e occupa gran parte della visuale.","textEn":"A large vehicle approaches and blocks a large part of your view."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Dietro la sua sagoma può esserci un altro veicolo che non riesci ancora a vedere.","textEn":"Another vehicle may be hidden behind its large profile."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Se quel veicolo sta sorpassando, può comparire improvvisamente sul lato esterno.","textEn":"If that vehicle is overtaking, it can suddenly appear on the outside."},{"at":6.9,"end":10,"event":"correct","textIt":"Aspetta: il veicolo grande può nascondere un veicolo in sorpasso.","textEn":"Wait: the large vehicle may hide an overtaking vehicle."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["largeVehicleHidesOvertaker_p0","largeVehicleHidesOvertaker_p1","largeVehicleHidesOvertaker_p2"],"hotspot":{"left":56,"top":50,"radiusX":40,"radiusY":36,"instructionIt":"TOCCA IL VEICOLO GRANDE","instructionEn":"TAP THE LARGE VEHICLE","ariaIt":"Tocca il grande veicolo che limita la visuale","ariaEn":"Tap the large vehicle blocking the view"},"phases":[{},{"titleIt":"VISUALE COPERTA","titleEn":"BLOCKED VIEW","bodyIt":"La sagoma del veicolo grande nasconde ciò che gli sta accanto o dietro.","bodyEn":"The large vehicle can hide what is beside or behind it."},{"titleIt":"VEICOLO NASCOSTO","titleEn":"HIDDEN VEHICLE","bodyIt":"Non presumere che la strada sia libera solo perché non vedi altro.","bodyEn":"Do not assume the road is clear just because you see nothing else."},{"titleIt":"SORPASSO NASCOSTO","titleEn":"HIDDEN OVERTAKER","bodyIt":"Un veicolo in sorpasso può emergere all’improvviso.","bodyEn":"An overtaking vehicle may suddenly emerge."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Chiediti cosa può essere nascosto dalla sagoma del camion.","missEn":"Ask what may be hidden by the truck’s large profile.","hitIt":"Esatto: può nascondere un veicolo che lo sta sorpassando.","hitEn":"Correct: it may hide a vehicle overtaking it."},"learning":{"correctIt":"A un incrocio aspetta quando un veicolo grande limita la visuale: può nascondere un veicolo in sorpasso.","correctEn":"At a junction, wait when a large vehicle blocks your view: it may hide an overtaking vehicle."}});




