global.ReplayEngine.registerScene({"id":"MT_ENGINE_OIL_CHANGE_INTERVALS_V1","category":"engine-maintenance","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"engineOilChangeIntervals","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Engine oil changes reduce friction and wear","accessibilityLabel":"Real close-up of engine oil being poured into a car engine during maintenance","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/8470297/","videoSources":["https://www.pexels.com/download/video/8470297/"],"poster":"https://images.pexels.com/videos/8470297/breakdown-car-painting-car-repair-driver-8470297.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Anastasia Shuraeva","sourcePage":"https://www.pexels.com/video/man-putting-oil-in-the-car-8470297/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"L’olio lubrifica le parti mobili del motore.","textEn":"Engine oil lubricates the moving parts."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Con il tempo l’olio si degrada e protegge meno.","textEn":"Over time the oil degrades and protects less."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Sostituirlo agli intervalli raccomandati mantiene una corretta lubrificazione.","textEn":"Changing it at the recommended intervals maintains proper lubrication."},{"at":6.9,"end":10,"event":"correct","textIt":"L’olio nuovo riduce attrito e usura.","textEn":"Fresh oil reduces friction and wear."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["engineOilChangeIntervals_p0","engineOilChangeIntervals_p1","engineOilChangeIntervals_p2"],"hotspot":{"left":54,"top":50,"radiusX":34,"radiusY":34,"instructionIt":"TOCCA L’OLIO MOTORE","instructionEn":"TAP THE ENGINE OIL","ariaIt":"Tocca l’olio versato nel motore","ariaEn":"Tap the oil being poured into the engine"},"phases":[{},{"titleIt":"OLIO MOTORE","titleEn":"ENGINE OIL","bodyIt":"L’olio lubrifica le parti mobili del motore.","bodyEn":"Engine oil lubricates the moving parts."},{"titleIt":"LUBRIFICAZIONE","titleEn":"LUBRICATION","bodyIt":"Con l’uso l’olio perde efficacia e va sostituito agli intervalli previsti.","bodyEn":"Oil loses effectiveness with use and should be changed at the recommended intervals."},{"titleIt":"MENO ATTRITO E USURA","titleEn":"LESS FRICTION AND WEAR","bodyIt":"Olio efficiente riduce attrito e usura.","bodyEn":"Effective oil reduces friction and wear."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Concentrati sulla funzione dell’olio tra le parti mobili del motore.","missEn":"Focus on what the oil does between moving engine parts.","hitIt":"Esatto: riduce attrito e usura.","hitEn":"Correct: it reduces friction and wear."},"learning":{"correctIt":"Sostituire l’olio motore agli intervalli raccomandati riduce attrito e usura.","correctEn":"Changing engine oil at the recommended intervals reduces friction and wear."}});

global.ReplayEngine.registerScene({"id":"MT_HEAVY_RAIN_DOUBLE_BRAKING_DISTANCE_V1","category":"wet-weather","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"heavyRainDoubleBrakingDistance","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Heavy rain: allow at least twice the normal braking distance","accessibilityLabel":"Real driver view through a windscreen during heavy rain with reduced visibility and a wet road","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/37883065/","videoSources":["https://www.pexels.com/download/video/37883065/"],"poster":"https://images.pexels.com/videos/37883065/pexels-photo-37883065.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Viola Bungard","sourcePage":"https://www.pexels.com/video/driving-through-heavy-rain-in-urban-area-37883065/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"La pioggia intensa bagna la carreggiata e limita la visuale.","textEn":"Heavy rain wets the road and limits visibility."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"L’aderenza diminuisce e il veicolo impiega più spazio per rallentare.","textEn":"Grip is reduced and the vehicle needs more space to slow down."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Devi aumentare in modo importante il margine di frenata rispetto all’asciutto.","textEn":"You must substantially increase the braking margin compared with dry conditions."},{"at":6.9,"end":10,"event":"correct","textIt":"Lascia almeno il doppio della normale distanza di frenata.","textEn":"Allow at least twice the normal braking distance."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["heavyRainDoubleBrakingDistance_p0","heavyRainDoubleBrakingDistance_p1","heavyRainDoubleBrakingDistance_p2"],"hotspot":{"left":50,"top":52,"radiusX":40,"radiusY":34,"instructionIt":"TOCCA LA STRADA BAGNATA","instructionEn":"TAP THE WET ROAD","ariaIt":"Tocca la strada visibile attraverso la pioggia intensa","ariaEn":"Tap the road visible through the heavy rain"},"phases":[{},{"titleIt":"PIOGGIA INTENSA","titleEn":"HEAVY RAIN","bodyIt":"Pioggia e acqua sulla carreggiata riducono visibilità e aderenza.","bodyEn":"Heavy rain and water on the road reduce visibility and grip."},{"titleIt":"ADERENZA RIDOTTA","titleEn":"REDUCED GRIP","bodyIt":"Sul bagnato serve più spazio per frenare in sicurezza.","bodyEn":"On a wet road you need more space to brake safely."},{"titleIt":"ALMENO IL DOPPIO","titleEn":"AT LEAST TWICE","bodyIt":"Lascia almeno il doppio della normale distanza di frenata.","bodyEn":"Allow at least twice the normal braking distance."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Pensa a come cambia l’aderenza quando la carreggiata è molto bagnata.","missEn":"Think about how grip changes when the road is very wet.","hitIt":"Esatto: almeno il doppio della distanza normale.","hitEn":"Correct: at least twice the normal distance."},"learning":{"correctIt":"Con pioggia intensa lascia almeno il doppio della normale distanza di frenata.","correctEn":"In heavy rain allow at least twice the normal braking distance."}});

global.ReplayEngine.registerScene({"id":"MT_COUNTRY_ROAD_HORSE_RIDERS_V1","category":"country-roads","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"countryRoadHorseRiders","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Country road: expect horse riders on your side","accessibilityLabel":"Real road scene with horse riders using a narrow country road","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/8624828/","videoSources":["https://www.pexels.com/download/video/8624828/"],"poster":"https://images.pexels.com/videos/8624828/adult-animal-beach-camel-8624828.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · RDNE Stock project","sourcePage":"https://www.pexels.com/video/people-riding-a-horse-8624828/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Davanti a te ci sono cavalieri sulla strada di campagna.","textEn":"Horse riders are ahead on the country road."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Un cavallo può aver bisogno di spazio e il cavaliere può stare lontano dal bordo.","textEn":"A horse may need space and the rider may keep away from the edge."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Non dare per scontato che il tuo lato della strada sia completamente libero.","textEn":"Do not assume your side of the road will be completely clear."},{"at":6.9,"end":10,"event":"correct","textIt":"Aspettati di vedere cavalieri arrivare verso di te sul tuo lato.","textEn":"Expect to see horse riders coming towards you on your side."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["countryRoadHorseRiders_p0","countryRoadHorseRiders_p1","countryRoadHorseRiders_p2"],"hotspot":{"left":32,"top":57,"radiusX":24,"radiusY":32,"instructionIt":"TOCCA I CAVALIERI","instructionEn":"TAP THE HORSE RIDERS","ariaIt":"Tocca i cavalieri che si avvicinano sulla strada","ariaEn":"Tap the horse riders approaching on the road"},"phases":[{},{"titleIt":"STRADA DI CAMPAGNA","titleEn":"COUNTRY ROAD","bodyIt":"Su una strada di campagna possono comparire utenti vulnerabili.","bodyEn":"Vulnerable road users may appear on a country road."},{"titleIt":"CAVALIERI SULLA STRADA","titleEn":"HORSE RIDERS ON THE ROAD","bodyIt":"I cavalieri possono usare la carreggiata e tenersi lontani dal bordo.","bodyEn":"Horse riders may use the carriageway and keep away from the edge."},{"titleIt":"POSSIBILI SUL TUO LATO","titleEn":"MAY BE ON YOUR SIDE","bodyIt":"Preparati a incontrarli anche sul tuo lato della strada.","bodyEn":"Be prepared to meet them even on your side of the road."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Cerca gli utenti vulnerabili che possono occupare parte della carreggiata.","missEn":"Look for vulnerable road users who may occupy part of the carriageway.","hitIt":"Esatto: su una strada di campagna puoi incontrare cavalieri.","hitEn":"Correct: on a country road you may meet horse riders."},"learning":{"correctIt":"Su una strada di campagna aspettati cavalieri anche sul tuo lato della carreggiata.","correctEn":"On a country road expect horse riders even on your side of the carriageway."}});

