global.ReplayEngine.registerScene({"id":"MT_STAY_CALM_WHEN_OVERTAKEN_V1","category":"attitude","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"stayCalmWhenOvertaken","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"When overtaken: stay calm and continue driving","accessibilityLabel":"Real road scene illustrating another vehicle overtaking while the driver maintains a steady course","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/4608282/","videoSources":["https://www.pexels.com/download/video/4608282/"],"poster":"https://images.pexels.com/videos/4608282/pexels-photo-4608282.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · K","sourcePage":"https://www.pexels.com/video/vehicle-overtaking-at-the-highway-4608282/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Un altro veicolo sta completando il sorpasso.","textEn":"Another vehicle is completing an overtake."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Accelerare o reagire può trasformare un normale sorpasso in un conflitto pericoloso.","textEn":"Accelerating or reacting can turn a normal overtake into a dangerous conflict."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Mantieni una guida regolare e prevedibile senza cercare di riprendere il veicolo.","textEn":"Keep your driving steady and predictable without trying to overtake back."},{"at":6.9,"end":10,"event":"correct","textIt":"Resta calmo e continua a guidare normalmente.","textEn":"Stay calm and continue driving normally."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["stayCalmWhenOvertaken_p0","stayCalmWhenOvertaken_p1","stayCalmWhenOvertaken_p2"],"hotspot":{"left":32,"top":55,"radiusX":28,"radiusY":30,"instructionIt":"TOCCA L’AUTO CHE SORPASSA","instructionEn":"TAP THE OVERTAKING CAR","ariaIt":"Tocca il veicolo che sta effettuando il sorpasso","ariaEn":"Tap the vehicle that is overtaking"},"phases":[{},{"titleIt":"TI STANNO SORPASSANDO","titleEn":"YOU ARE BEING OVERTAKEN","bodyIt":"Un altro conducente sta passando oltre il tuo veicolo.","bodyEn":"Another driver is passing your vehicle."},{"titleIt":"NON COMPETERE","titleEn":"DO NOT COMPETE","bodyIt":"Non accelerare, non inseguire e non reagire.","bodyEn":"Do not accelerate, chase, or retaliate."},{"titleIt":"RESTA CALMO","titleEn":"STAY CALM","bodyIt":"Mantieni una guida regolare e continua il tuo percorso.","bodyEn":"Keep a steady course and continue your journey."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Concentrati sulla tua reazione mentre l’altro veicolo ti sorpassa.","missEn":"Focus on your reaction while the other vehicle overtakes.","hitIt":"Esatto: niente competizione, resta calmo e continua.","hitEn":"Correct: do not compete; stay calm and continue."},"learning":{"correctIt":"Se un altro conducente ti sorpassa, resta calmo e continua a guidare senza reagire.","correctEn":"If another driver overtakes you, stay calm and continue driving without retaliating."}});

global.ReplayEngine.registerScene({"id":"MT_ROUGH_WEATHER_DRIVE_CAUTIOUSLY_V1","category":"weather","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"roughWeatherDriveCautiously","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Rough weather: drive more cautiously","accessibilityLabel":"Real driver view in heavy rain and fog with poor visibility and wet road surface","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/12611001/","videoSources":["https://www.pexels.com/download/video/12611001/"],"poster":"https://images.pexels.com/videos/12611001/beauty-of-nature-drive-heavy-rain-raining-12611001.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · aksinfo7 universe","sourcePage":"https://www.pexels.com/video/heavy-rain-and-fog-on-highway-12611001/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Pioggia intensa e foschia riducono la visibilità e l’aderenza.","textEn":"Heavy rain and mist reduce visibility and grip."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Lo spazio necessario per reagire e fermarsi aumenta.","textEn":"You need more space to react and stop."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Riduci la velocità, aumenta la distanza e anticipa i pericoli.","textEn":"Reduce speed, increase your following distance, and anticipate hazards."},{"at":6.9,"end":10,"event":"correct","textIt":"Con maltempo o condizioni pericolose guida con maggiore prudenza.","textEn":"In rough weather or dangerous conditions, drive more cautiously."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["roughWeatherDriveCautiously_p0","roughWeatherDriveCautiously_p1","roughWeatherDriveCautiously_p2"],"hotspot":{"left":55,"top":58,"radiusX":38,"radiusY":32,"instructionIt":"TOCCA LA STRADA BAGNATA","instructionEn":"TAP THE WET ROAD","ariaIt":"Tocca la strada con visibilità ridotta e fondo bagnato","ariaEn":"Tap the road with poor visibility and wet surface"},"phases":[{},{"titleIt":"VISIBILITÀ RIDOTTA","titleEn":"REDUCED VISIBILITY","bodyIt":"Pioggia e foschia rendono più difficile vedere i pericoli in tempo.","bodyEn":"Rain and mist make it harder to see hazards in time."},{"titleIt":"MENO ADERENZA","titleEn":"LESS GRIP","bodyIt":"Sul bagnato servono più spazio e manovre più dolci.","bodyEn":"On wet roads you need more space and smoother inputs."},{"titleIt":"GUIDA PIÙ PRUDENTE","titleEn":"DRIVE MORE CAUTIOUSLY","bodyIt":"Riduci la velocità e aumenta la distanza di sicurezza.","bodyEn":"Reduce speed and increase your safety distance."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Guarda quanto pioggia e foschia riducono visibilità e aderenza.","missEn":"Notice how rain and mist reduce visibility and grip.","hitIt":"Esatto: con queste condizioni devi guidare con maggiore prudenza.","hitEn":"Correct: in these conditions you must drive more cautiously."},"learning":{"correctIt":"Con maltempo o condizioni pericolose riduci la velocità, aumenta la distanza e guida con maggiore prudenza.","correctEn":"In rough weather or dangerous conditions, reduce speed, increase distance, and drive more cautiously."}});

global.ReplayEngine.registerScene({"id":"MT_WEEKLY_TYRE_PRESSURE_CHECK_V1","category":"tyres","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"weeklyTyrePressureCheck","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Tyre pressure: check it at least every week","accessibilityLabel":"Real close-up of a car tyre connected to an air pump for tyre pressure maintenance","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/8651811/","videoSources":["https://www.pexels.com/download/video/8651811/"],"poster":"https://images.pexels.com/videos/8651811/oldtimer-8651811.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Ojyrai Films","sourcePage":"https://www.pexels.com/video/a-person-using-air-pump-on-a-tire-of-a-car-8651811/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"La pressione degli pneumatici va controllata regolarmente.","textEn":"Tyre pressure needs to be checked regularly."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Una pressione errata può peggiorare tenuta, sterzo e consumo dello pneumatico.","textEn":"Incorrect pressure can affect grip, steering, and tyre wear."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Il controllo frequente permette di correggere presto eventuali perdite di pressione.","textEn":"Frequent checks let you correct pressure loss early."},{"at":6.9,"end":10,"event":"correct","textIt":"Controlla la pressione almeno ogni settimana.","textEn":"Check tyre pressure at least every week."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["weeklyTyrePressureCheck_p0","weeklyTyrePressureCheck_p1","weeklyTyrePressureCheck_p2"],"hotspot":{"left":55,"top":56,"radiusX":30,"radiusY":32,"instructionIt":"TOCCA LO PNEUMATICO","instructionEn":"TAP THE TYRE","ariaIt":"Tocca lo pneumatico su cui viene controllata la pressione","ariaEn":"Tap the tyre whose pressure is being checked"},"phases":[{},{"titleIt":"CONTROLLA LA PRESSIONE","titleEn":"CHECK THE PRESSURE","bodyIt":"Usa un manometro o un sistema di gonfiaggio affidabile.","bodyEn":"Use a reliable gauge or inflation system."},{"titleIt":"CONTROLLO REGOLARE","titleEn":"CHECK REGULARLY","bodyIt":"Non aspettare che lo pneumatico sembri visibilmente sgonfio.","bodyEn":"Do not wait until the tyre looks visibly under-inflated."},{"titleIt":"ALMENO OGNI SETTIMANA","titleEn":"AT LEAST WEEKLY","bodyIt":"La frequenza minima indicata è una volta alla settimana.","bodyEn":"The minimum recommended frequency is once a week."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Concentrati sul controllo della pressione dello pneumatico.","missEn":"Focus on the tyre-pressure check.","hitIt":"Esatto: la pressione va controllata almeno ogni settimana.","hitEn":"Correct: tyre pressure should be checked at least weekly."},"learning":{"correctIt":"Controlla la pressione degli pneumatici almeno ogni settimana.","correctEn":"Check tyre pressure at least every week."}});

global.ReplayEngine.registerScene({"id":"MT_UNDER_INFLATED_TYRES_HEAVY_STEERING_V1","category":"vehicle-faults","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"underInflatedTyresHeavySteering","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Under-inflated tyres can cause heavy steering","accessibilityLabel":"Real car tyre being inflated after loss of pressure, illustrating an under-inflation condition","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/8651800/","videoSources":["https://www.pexels.com/download/video/8651800/"],"poster":"https://images.pexels.com/videos/8651800/pexels-photo-8651800.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Ojyrai Films","sourcePage":"https://www.pexels.com/video/a-woman-inflating-car-tire-using-a-foot-pump-8651800/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Uno pneumatico con pressione troppo bassa si deforma maggiormente a contatto con la strada.","textEn":"A tyre with pressure that is too low deforms more against the road."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"La maggiore resistenza al rotolamento può rendere il veicolo più faticoso da sterzare.","textEn":"The extra rolling resistance can make the vehicle harder to steer."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Se lo sterzo diventa insolitamente pesante, controlla anche la pressione degli pneumatici.","textEn":"If the steering becomes unusually heavy, check the tyre pressures too."},{"at":6.9,"end":10,"event":"correct","textIt":"Pneumatici sgonfi possono causare uno sterzo pesante.","textEn":"Under-inflated tyres can cause heavy steering."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["underInflatedTyresHeavySteering_p0","underInflatedTyresHeavySteering_p1","underInflatedTyresHeavySteering_p2"],"hotspot":{"left":55,"top":58,"radiusX":30,"radiusY":32,"instructionIt":"TOCCA LO PNEUMATICO","instructionEn":"TAP THE TYRE","ariaIt":"Tocca lo pneumatico con pressione insufficiente","ariaEn":"Tap the tyre with insufficient pressure"},"phases":[{},{"titleIt":"PRESSIONE BASSA","titleEn":"LOW PRESSURE","bodyIt":"Uno pneumatico sgonfio si deforma più del normale.","bodyEn":"An under-inflated tyre deforms more than normal."},{"titleIt":"PIÙ RESISTENZA","titleEn":"MORE RESISTANCE","bodyIt":"Aumenta la resistenza al rotolamento e lo sforzo richiesto allo sterzo.","bodyEn":"Rolling resistance and steering effort increase."},{"titleIt":"STERZO PESANTE","titleEn":"HEAVY STEERING","bodyIt":"Una causa possibile è la pressione troppo bassa degli pneumatici.","bodyEn":"One possible cause is under-inflated tyres."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Guarda la condizione dello pneumatico e pensa a come influisce sullo sterzo.","missEn":"Look at the tyre condition and how it affects steering effort.","hitIt":"Esatto: pneumatici sgonfi possono rendere lo sterzo pesante.","hitEn":"Correct: under-inflated tyres can make the steering heavy."},"learning":{"correctIt":"Pneumatici sgonfi aumentano lo sforzo sullo sterzo e possono causare sterzo pesante.","correctEn":"Under-inflated tyres increase steering effort and can cause heavy steering."}});



