global.ReplayEngine.registerScene({"id":"MT_NO_OVERTAKE_HAZARD_CONDITIONS_V1","category":"overtaking","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"noOvertakeHazardConditions","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Do not overtake with restricted view, near a junction, or before turning","accessibilityLabel":"Real traffic navigating a winding road where forward visibility is restricted, reinforcing situations where overtaking must be avoided","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/27662469/","videoSources":["https://www.pexels.com/download/video/27662469/"],"poster":"https://images.pexels.com/videos/27662469/cars-mountain-night-27662469.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Atif Dar","sourcePage":"https://www.pexels.com/video/a-car-is-parked-on-the-side-of-the-road-at-night-27662469/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Prima di sorpassare devi poter vedere chiaramente cosa c’è davanti.","textEn":"Before overtaking you must be able to see clearly ahead."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Visuale ostruita, incrocio vicino o svolta a sinistra poco dopo rendono il sorpasso non sicuro.","textEn":"A blocked view, a nearby junction or an imminent left turn make overtaking unsafe."},{"at":4.5,"end":6.8,"event":"explain","textIt":"In queste situazioni resta dietro e rinvia il sorpasso.","textEn":"In these situations stay behind and postpone the overtake."},{"at":6.9,"end":10,"event":"correct","textIt":"Non sorpassare senza visuale libera, vicino agli incroci o prima di svoltare a sinistra.","textEn":"Do not overtake without a clear view, near junctions or before turning left."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["noOvertakeHazardConditions_p0","noOvertakeHazardConditions_p1","noOvertakeHazardConditions_p2"],"hotspot":{"left":50,"top":52,"radiusX":38,"radiusY":32,"instructionIt":"TOCCA LA ZONA DI PERICOLO","instructionEn":"TAP THE HAZARD AREA","ariaIt":"Tocca la parte di strada dove la visuale è limitata","ariaEn":"Tap the road area where visibility is restricted"},"phases":[{},{"titleIt":"VISUALE OSTRUITA","titleEn":"BLOCKED VIEW","bodyIt":"Se non puoi vedere bene davanti, non iniziare il sorpasso.","bodyEn":"If you cannot see clearly ahead, do not start overtaking."},{"titleIt":"INCROCIO VICINO","titleEn":"JUNCTION AHEAD","bodyIt":"Avvicinandoti a un incrocio devi evitare il sorpasso.","bodyEn":"Avoid overtaking when approaching a junction."},{"titleIt":"SVOLTA A SINISTRA","titleEn":"LEFT TURN SOON","bodyIt":"Se devi girare a sinistra poco dopo, resta dietro.","bodyEn":"If you intend to turn left shortly afterwards, stay behind."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Cerca ciò che rende il sorpasso non sicuro: visuale, incrocio o svolta imminente.","missEn":"Look for what makes overtaking unsafe: visibility, a junction or an imminent turn.","hitIt":"Esatto: in queste condizioni il sorpasso va evitato.","hitEn":"Correct: overtaking should be avoided in these conditions."},"learning":{"correctIt":"Non sorpassare con visuale ostruita, vicino a un incrocio o prima di svoltare a sinistra.","correctEn":"Do not overtake with a blocked view, near a junction or before turning left."}});

global.ReplayEngine.registerScene({"id":"MT_DEFENSIVE_DRIVING_ANTICIPATE_HAZARDS_V1","category":"defensive-driving","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"defensiveDrivingAnticipateHazards","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Defensive driving: anticipate hazards and others' actions","accessibilityLabel":"Real driver staying alert and focused while driving through city streets, illustrating defensive driving awareness","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/9530761/","videoSources":["https://www.pexels.com/download/video/9530761/"],"poster":"https://images.pexels.com/videos/9530761/80s-at-night-car-cinematic-9530761.jpeg?dpr=1&h=750&w=1260","credit":"Pexels · Ron Lach","sourcePage":"https://www.pexels.com/video/man-driving-a-car-9530761/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Osserva continuamente strada, traffico e possibili errori degli altri.","textEn":"Continuously observe the road, traffic and possible mistakes by others."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Un pericolo può svilupparsi anche se tu stai guidando correttamente.","textEn":"A hazard can develop even when you are driving correctly."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Anticipa ciò che potrebbe accadere e conserva sempre un margine di sicurezza.","textEn":"Anticipate what may happen and always keep a safety margin."},{"at":6.9,"end":10,"event":"correct","textIt":"La guida difensiva significa guidare in sicurezza nonostante le condizioni e le azioni degli altri.","textEn":"Defensive driving means driving safely despite conditions and the actions of others."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["defensiveDrivingAnticipateHazards_p0","defensiveDrivingAnticipateHazards_p1","defensiveDrivingAnticipateHazards_p2"],"hotspot":{"left":50,"top":52,"radiusX":38,"radiusY":32,"instructionIt":"TOCCA LA STRADA DAVANTI","instructionEn":"TAP THE ROAD AHEAD","ariaIt":"Tocca la zona di strada che il conducente deve continuare a controllare","ariaEn":"Tap the road area the driver must keep scanning"},"phases":[{},{"titleIt":"OSSERVA","titleEn":"OBSERVE","bodyIt":"Controlla continuamente strada, traffico e utenti vulnerabili.","bodyEn":"Continuously scan the road, traffic and vulnerable road users."},{"titleIt":"ANTICIPA","titleEn":"ANTICIPATE","bodyIt":"Prevedi possibili errori o movimenti improvvisi degli altri.","bodyEn":"Anticipate possible mistakes or sudden movements by others."},{"titleIt":"CREA MARGINE","titleEn":"KEEP A MARGIN","bodyIt":"Velocità e distanza devono lasciarti tempo per reagire.","bodyEn":"Speed and distance must leave you time to react."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Pensa ad anticipare i pericoli, non soltanto a reagire quando sono già presenti.","missEn":"Think about anticipating hazards, not only reacting once they appear.","hitIt":"Esatto: osservare, anticipare e mantenere margine è guida difensiva.","hitEn":"Correct: observing, anticipating and keeping a margin is defensive driving."},"learning":{"correctIt":"Guida difensiva = anticipare i pericoli e proteggersi dagli errori degli altri.","correctEn":"Defensive driving means anticipating hazards and protecting yourself from others' mistakes."}});

global.ReplayEngine.registerScene({"id":"MT_AVOID_DISTRACTIONS_STAY_FOCUSED_V1","category":"distractions","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"avoidDistractionsStayFocused","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Avoid distractions and stay focused on the road","accessibilityLabel":"Real driver focused on the road from inside a moving car, illustrating full attention while driving","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/3683320/","videoSources":["https://www.pexels.com/download/video/3683320/"],"poster":"https://images.pexels.com/videos/3683320/pexels-photo-3683320.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · samazing family","sourcePage":"https://www.pexels.com/video/woman-focusing-on-her-driving-3683320/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Durante la guida la tua attenzione deve rimanere sulla strada.","textEn":"While driving your attention must remain on the road."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Telefono, conversazioni o altre distrazioni possono togliere occhi e mente dalla guida.","textEn":"Phones, conversations or other distractions can take your eyes and mind away from driving."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Elimina o rimanda ciò che non è necessario mentre il veicolo è in movimento.","textEn":"Remove or postpone anything unnecessary while the vehicle is moving."},{"at":6.9,"end":10,"event":"correct","textIt":"Il conducente deve evitare tutte le distrazioni e mantenere piena attenzione.","textEn":"A driver should avoid all distractions and maintain full attention."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["avoidDistractionsStayFocused_p0","avoidDistractionsStayFocused_p1","avoidDistractionsStayFocused_p2"],"hotspot":{"left":50,"top":52,"radiusX":38,"radiusY":32,"instructionIt":"TOCCA LA STRADA","instructionEn":"TAP THE ROAD","ariaIt":"Tocca la zona davanti su cui il conducente deve mantenere l'attenzione","ariaEn":"Tap the area ahead where the driver must keep attention"},"phases":[{},{"titleIt":"DISTRAZIONE","titleEn":"DISTRACTION","bodyIt":"Qualsiasi attività secondaria può ridurre l’attenzione alla guida.","bodyEn":"Any secondary activity can reduce driving attention."},{"titleIt":"OCCHI SULLA STRADA","titleEn":"EYES ON ROAD","bodyIt":"Mantieni lo sguardo sulla strada e sugli utenti attorno a te.","bodyEn":"Keep your eyes on the road and surrounding road users."},{"titleIt":"ATTENZIONE PIENA","titleEn":"FULL ATTENTION","bodyIt":"Mente e mani devono restare dedicate alla guida.","bodyEn":"Your mind and hands should remain dedicated to driving."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"La priorità è mantenere l’attenzione completa sulla guida.","missEn":"The priority is keeping full attention on driving.","hitIt":"Esatto: niente distrazioni, attenzione piena sulla strada.","hitEn":"Correct: no distractions, full attention on the road."},"learning":{"correctIt":"Evita tutte le distrazioni e resta concentrato sulla strada.","correctEn":"Avoid all distractions and stay focused on the road."}});

global.ReplayEngine.registerScene({"id":"MT_INJURY_ACCIDENT_CALL_112_ASSIST_V1","category":"accidents","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"injuryAccidentCall112Assist","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Injury accident: call 112 and provide assistance","accessibilityLabel":"Real paramedics assisting an injured person, illustrating the emergency response required after an injury accident","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/8944325/","videoSources":["https://www.pexels.com/download/video/8944325/"],"poster":"https://images.pexels.com/videos/8944325/pexels-photo-8944325.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Mikhail Nilov","sourcePage":"https://www.pexels.com/video/paramedics-rescuing-a-person-8944325/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Se un incidente ha causato feriti, prima proteggi la scena senza creare altro pericolo.","textEn":"If an accident has caused injuries, first protect the scene without creating further danger."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Una persona ferita può avere bisogno di assistenza urgente.","textEn":"An injured person may need urgent assistance."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Chiama subito i servizi di emergenza al 112 e presta ragionevole assistenza.","textEn":"Call the emergency services on 112 immediately and provide reasonable assistance."},{"at":6.9,"end":10,"event":"correct","textIt":"Con feriti: chiama il 112 e presta assistenza senza mettere in pericolo te stesso o altri.","textEn":"With injuries: call 112 and provide assistance without putting yourself or others in danger."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["injuryAccidentCall112Assist_p0","injuryAccidentCall112Assist_p1","injuryAccidentCall112Assist_p2"],"hotspot":{"left":50,"top":54,"radiusX":34,"radiusY":34,"instructionIt":"TOCCA LA PERSONA ASSISTITA","instructionEn":"TAP THE CASUALTY","ariaIt":"Tocca la zona dove viene prestata assistenza alla persona ferita","ariaEn":"Tap the area where assistance is being given to the injured person"},"phases":[{},{"titleIt":"FERMATI IN SICUREZZA","titleEn":"STOP SAFELY","bodyIt":"Non creare un secondo pericolo mentre ti occupi dell’incidente.","bodyEn":"Do not create a second hazard while dealing with the accident."},{"titleIt":"CHIAMA 112","titleEn":"CALL 112","bodyIt":"Comunica ai servizi di emergenza che ci sono persone ferite.","bodyEn":"Tell the emergency services that people are injured."},{"titleIt":"PRESTA ASSISTENZA","titleEn":"PROVIDE ASSISTANCE","bodyIt":"Resta sul posto e presta ragionevole assistenza in sicurezza.","bodyEn":"Remain at the scene and provide reasonable assistance safely."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Concentrati sulla risposta corretta a un incidente con feriti: emergenza e assistenza.","missEn":"Focus on the correct response to an injury accident: emergency call and assistance.","hitIt":"Esatto: 112 e ragionevole assistenza.","hitEn":"Correct: call 112 and provide reasonable assistance."},"learning":{"correctIt":"Se qualcuno è ferito, chiama il 112 e presta ragionevole assistenza.","correctEn":"If someone is injured, call 112 and provide reasonable assistance."}});

global.ReplayEngine.registerScene({"id":"MT_ROADWORKS_MOTORCYCLIST_EXTRA_ROOM_V1","category":"motorcyclists","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"roadworksMotorcyclistExtraRoom","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Roadworks: give motorcyclists extra room","accessibilityLabel":"Real motorcycles and vehicles passing an urban road construction area, illustrating the need to give riders extra lateral room","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/30027770/","videoSources":["https://www.pexels.com/download/video/30027770/"],"poster":"https://images.pexels.com/videos/30027770/construction-building-roads-30027770.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Toàn BDS","sourcePage":"https://www.pexels.com/video/urban-construction-site-with-passing-traffic-30027770/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Nei lavori stradali il fondo può essere irregolare, con buche o materiale smosso.","textEn":"At roadworks the surface may be uneven, with potholes or loose material."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Un motociclista può dover cambiare linea improvvisamente per evitare un ostacolo.","textEn":"A motorcyclist may need to change line suddenly to avoid an obstacle."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Non passargli vicino: lascia spazio laterale sufficiente per una deviazione.","textEn":"Do not pass close: leave enough lateral space for a sudden swerve."},{"at":6.9,"end":10,"event":"correct","textIt":"Lascia più spazio ai motociclisti nei lavori stradali perché possono deviare per evitare buche o fondo sconnesso.","textEn":"Give motorcyclists extra room at roadworks because they may swerve to avoid potholes or uneven surfaces."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["roadworksMotorcyclistExtraRoom_p0","roadworksMotorcyclistExtraRoom_p1","roadworksMotorcyclistExtraRoom_p2"],"hotspot":{"left":54,"top":52,"radiusX":34,"radiusY":34,"instructionIt":"TOCCA IL MOTOCICLISTA","instructionEn":"TAP THE MOTORCYCLIST","ariaIt":"Tocca il motociclista a cui devi lasciare più spazio","ariaEn":"Tap the motorcyclist you should give extra room"},"phases":[{},{"titleIt":"LAVORI STRADALI","titleEn":"ROADWORKS","bodyIt":"Aspettati fondo irregolare e ostacoli temporanei.","bodyEn":"Expect uneven surfaces and temporary obstacles."},{"titleIt":"BUCHE / FONDO SCONNESSO","titleEn":"POTHOLES / UNEVEN SURFACE","bodyIt":"Le due ruote sono più sensibili a buche e materiale smosso.","bodyEn":"Two-wheelers are more sensitive to potholes and loose material."},{"titleIt":"DEVIAZIONE IMPROVVISA","titleEn":"SUDDEN SWERVE","bodyIt":"Il motociclista può spostarsi rapidamente per evitare un ostacolo.","bodyEn":"The rider may move suddenly to avoid an obstacle."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Guarda il motociclista e pensa a cosa può fare davanti a una buca.","missEn":"Look at the rider and think what they may do when facing a pothole.","hitIt":"Esatto: può deviare all’improvviso, quindi lascia più spazio.","hitEn":"Correct: they may swerve suddenly, so give extra room."},"learning":{"correctIt":"Nei lavori stradali lascia più spazio ai motociclisti: possono deviare per evitare buche o fondo sconnesso.","correctEn":"At roadworks give motorcyclists extra room: they may swerve to avoid potholes or uneven surfaces."}});


