global.ReplayEngine.registerScene({"id":"MT_BUS_STOP_TWELVE_METRES_CLEAR_V1","category":"parking","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"busStopTwelveMetresClear","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Bus stop: leave 12 metres clear on each side","accessibilityLabel":"Real public bus at an urban bus stop area, illustrating why the space around a bus stop must be kept clear for safe access","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/5402042/","videoSources":["https://www.pexels.com/download/video/5402042/"],"poster":"https://images.pexels.com/videos/5402042/buses-car-s-central-london-city-of-london-5402042.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · George Morina","sourcePage":"https://www.pexels.com/video/a-double-decker-bus-stopping-at-a-bus-stop-5402042/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Una fermata autobus deve avere spazio sufficiente per l'accosto e la ripartenza del mezzo.","textEn":"A bus stop needs enough clear space for the bus to pull in and move off."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Parcheggiare troppo vicino può ostacolare il bus e i passeggeri.","textEn":"Parking too close can obstruct the bus and its passengers."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Lascia liberi 12 metri su ciascun lato della fermata o fare stage.","textEn":"Leave 12 metres clear on each side of a bus stop or fare stage."},{"at":6.9,"end":10,"event":"correct","textIt":"La distanza da ricordare è 12 metri per lato.","textEn":"The distance to remember is 12 metres on each side."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["busStopTwelveMetresClear_p0","busStopTwelveMetresClear_p1","busStopTwelveMetresClear_p2"],"hotspot":{"left":53,"top":52,"radiusX":38,"radiusY":31,"instructionIt":"TOCCA LA ZONA DELLA FERMATA","instructionEn":"TAP THE BUS STOP AREA","ariaIt":"Tocca la zona attorno alla fermata che deve restare libera","ariaEn":"Tap the area around the bus stop that must be kept clear"},"phases":[{},{"titleIt":"FERMATA AUTOBUS","titleEn":"BUS STOP","bodyIt":"Il bus deve poter accostare senza ostacoli.","bodyEn":"The bus must be able to pull in without obstruction."},{"titleIt":"SPAZIO LIBERO","titleEn":"KEEP IT CLEAR","bodyIt":"Non parcheggiare troppo vicino alla fermata.","bodyEn":"Do not park too close to the stop."},{"titleIt":"12 METRI PER LATO","titleEn":"12 METRES EACH SIDE","bodyIt":"Mantieni 12 metri liberi su entrambi i lati.","bodyEn":"Keep 12 metres clear on both sides."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Pensa allo spazio necessario al bus per accostare e ripartire.","missEn":"Think about the space a bus needs to pull in and move off.","hitIt":"Esatto: 12 metri liberi su ciascun lato.","hitEn":"Correct: 12 metres clear on each side."},"learning":{"correctIt":"Lascia 12 metri liberi su ciascun lato di una fermata autobus o fare stage.","correctEn":"Leave 12 metres clear on each side of a bus stop or fare stage."}});



