global.ReplayEngine.registerScene({"id":"MT_MICROSLEEP_INVOLUNTARY_EPISODE_V1","category":"fatigue","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"microsleepInvoluntaryEpisode","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Microsleep: a brief involuntary episode of sleep","accessibilityLabel":"Real tired driver at night illustrating loss of alertness and microsleep risk","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/9531464/","videoSources":["https://www.pexels.com/download/video/9531464/"],"poster":"https://images.pexels.com/videos/9531464/at-night-car-cinematic-driver-9531464.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Ron Lach","sourcePage":"https://www.pexels.com/video/a-tired-man-driving-a-car-9531464/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"La stanchezza può far perdere attenzione anche per pochissimi secondi.","textEn":"Fatigue can make you lose attention even for a few seconds."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Un microsleep può avvenire involontariamente mentre sei ancora al volante.","textEn":"A microsleep can happen involuntarily while you are still at the wheel."},{"at":4.5,"end":6.8,"event":"explain","textIt":"È un brevissimo episodio di sonno o perdita di attenzione.","textEn":"It is a very brief episode of sleep or loss of attention."},{"at":6.9,"end":10,"event":"correct","textIt":"Microsleep = brevissimo sonno involontario o perdita di attenzione.","textEn":"Microsleep = a very brief involuntary sleep episode or loss of attention."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["microsleepInvoluntaryEpisode_p0","microsleepInvoluntaryEpisode_p1","microsleepInvoluntaryEpisode_p2"],"hotspot":{"left":60,"top":42,"radiusX":30,"radiusY":34,"instructionIt":"TOCCA IL CONDUCENTE STANCO","instructionEn":"TAP THE TIRED DRIVER","ariaIt":"Tocca il conducente che mostra segni di stanchezza","ariaEn":"Tap the driver showing signs of fatigue"},"phases":[{},{"titleIt":"STANCHEZZA","titleEn":"FATIGUE","bodyIt":"La vigilanza cala e i tempi di reazione peggiorano.","bodyEn":"Alertness drops and reaction time worsens."},{"titleIt":"POCHI SECONDI","titleEn":"A FEW SECONDS","bodyIt":"Puoi perdere attenzione senza rendertene conto.","bodyEn":"You can lose attention without realising it."},{"titleIt":"MICROSLEEP","titleEn":"MICROSLEEP","bodyIt":"È un brevissimo episodio involontario di sonno o perdita di attenzione.","bodyEn":"It is a very brief involuntary episode of sleep or loss of attention."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Cerca il concetto chiave: sonno brevissimo e involontario.","missEn":"Focus on the key idea: a very brief involuntary sleep episode.","hitIt":"Esatto: un microsleep è un brevissimo episodio involontario di sonno.","hitEn":"Correct: a microsleep is a very brief involuntary sleep episode."},"learning":{"correctIt":"Il microsleep è un brevissimo episodio involontario di sonno o perdita di attenzione.","correctEn":"A microsleep is a very brief involuntary episode of sleep or loss of attention."}});

global.ReplayEngine.registerScene({"id":"MT_TOO_TIRED_USE_ALTERNATIVE_TRANSPORT_V1","category":"fatigue","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"tooTiredUseAlternativeTransport","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Too tired to drive: use alternative transport","accessibilityLabel":"Real person sleeping in a car, illustrating the safe choice to rest or be transported rather than drive while exhausted","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/9340841/","videoSources":["https://www.pexels.com/download/video/9340841/"],"poster":"https://images.pexels.com/videos/9340841/air-aircraft-airplane-car-9340841.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels · Marina Leonova","sourcePage":"https://www.pexels.com/video/a-person-sleeping-in-a-car-9340841/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Se sei troppo stanco, la scelta sicura è non metterti alla guida.","textEn":"If you are too tired, the safe choice is not to drive."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Caffè, aria fresca o fretta non eliminano il rischio della stanchezza.","textEn":"Coffee, fresh air or rushing do not remove the risk from fatigue."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Riposa oppure fatti accompagnare o usa il trasporto pubblico.","textEn":"Rest, get a lift, or use public transport."},{"at":6.9,"end":10,"event":"correct","textIt":"Troppo stanco? Non guidare: usa un altro mezzo o fatti accompagnare.","textEn":"Too tired? Do not drive: use another form of transport or get a lift."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["tooTiredUseAlternativeTransport_p0","tooTiredUseAlternativeTransport_p1","tooTiredUseAlternativeTransport_p2"],"hotspot":{"left":50,"top":58,"radiusX":36,"radiusY":30,"instructionIt":"TOCCA LA PERSONA CHE RIPOSA","instructionEn":"TAP THE RESTING PERSON","ariaIt":"Tocca la persona che sta riposando invece di guidare","ariaEn":"Tap the person resting instead of driving"},"phases":[{},{"titleIt":"TROPPO STANCO","titleEn":"TOO TIRED","bodyIt":"Non iniziare o continuare il viaggio al volante.","bodyEn":"Do not start or continue the journey at the wheel."},{"titleIt":"NON BASTA IL CAFFÈ","titleEn":"COFFEE IS NOT ENOUGH","bodyIt":"I rimedi improvvisati non rendono sicura la guida.","bodyEn":"Quick fixes do not make driving safe."},{"titleIt":"ALTRO MEZZO","titleEn":"ALTERNATIVE TRANSPORT","bodyIt":"Fatti accompagnare, usa il trasporto pubblico o riposa.","bodyEn":"Get a lift, use public transport, or rest."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Se la stanchezza è forte, la soluzione non è continuare a guidare.","missEn":"If fatigue is severe, the solution is not to keep driving.","hitIt":"Esatto: non guidare e usa un'alternativa sicura.","hitEn":"Correct: do not drive and use a safe alternative."},"learning":{"correctIt":"Se sei troppo stanco per guidare, usa il trasporto pubblico o fatti accompagnare.","correctEn":"If you are too tired to drive, use public transport or get a lift."}});

