global.ReplayEngine.registerScene({"id":"MT_HORSE_ROUNDABOUT_DIRECTION_190_V1","category":"horse-riders","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"horseRoundaboutDirection190","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Horse rider at a roundabout: do not assume direction","accessibilityLabel":"Horse rider travelling on the road while traffic keeps a safe distance","playbackRate":0.9,"media":{"video":"https://www.pexels.com/download/video/8625307/","videoSources":["https://www.pexels.com/download/video/8625307/"],"poster":"https://images.pexels.com/videos/8625307/adult-animal-car-cattle-8625307.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels — RDNE Stock project","sourcePage":"https://www.pexels.com/video/people-doing-horseback-riding-on-the-road-8625307/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Un cavaliere è davanti a te mentre si avvicina alla rotatoria.","textEn":"A horse rider is ahead as you approach the roundabout."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"La sua posizione nella corsia non indica con certezza quale uscita prenderà.","textEn":"The rider's lane position does not reliably tell you which exit they will take."},{"at":4.5,"end":6.8,"event":"explain","textIt":"I cavalieri possono scegliere una posizione diversa per sicurezza e visibilità.","textEn":"Horse riders may use a different road position for safety and visibility."},{"at":6.9,"end":10,"event":"correct","textIt":"Aspettati che il cavaliere possa andare in qualsiasi direzione.","textEn":"Expect the horse rider to go in any direction."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["horseDirection190_p0","horseDirection190_p1","horseDirection190_p2"],"hotspot":{"left":49,"top":56,"radiusX":35,"radiusY":31,"instructionIt":"TOCCA IL CAVALIERE","instructionEn":"TAP THE HORSE RIDER","ariaIt":"Tocca il cavaliere davanti al veicolo","ariaEn":"Tap the horse rider ahead"},"phases":[{},{"titleIt":"CAVALIERE DAVANTI","titleEn":"HORSE RIDER AHEAD","bodyIt":"Osserva il cavaliere e mantieni spazio sufficiente.","bodyEn":"Watch the horse rider and keep enough space."},{"titleIt":"NON PRESUMERE LA DIREZIONE","titleEn":"DO NOT ASSUME DIRECTION","bodyIt":"La posizione nella corsia non ti dice con certezza dove svolterà.","bodyEn":"Lane position does not tell you for certain where the rider will turn."},{"titleIt":"PUÒ ANDARE IN QUALSIASI DIREZIONE","titleEn":"EXPECT ANY DIRECTION","bodyIt":"Alla rotatoria devi aspettarti qualunque direzione e restare prudente.","bodyEn":"At the roundabout, expect any direction and remain cautious."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Guarda il cavaliere e non dedurre la direzione solo dalla sua posizione.","missEn":"Watch the horse rider and do not infer direction from road position alone.","hitIt":"Esatto: il cavaliere potrebbe prendere qualsiasi direzione.","hitEn":"Correct: the horse rider may go in any direction."},"learning":{"correctIt":"Alla rotatoria, la posizione di un cavaliere non indica necessariamente la sua direzione: aspettati che possa andare ovunque.","correctEn":"At a roundabout, a horse rider's position does not necessarily show direction: expect them to go in any direction."}});

global.ReplayEngine.registerScene({"id":"MT_HORSES_ROUNDABOUT_ROOM_STOP_190_V1","category":"horse-riders","country":"MT","licenceType":"LPTV","drivingSide":"left","countryPackId":"MT-LPTV","sceneKey":"horsesRoundaboutRoomStop190","visualStatus":"final-real-footage","replayTemplate":"standard-video","title":"Horses at a roundabout: leave room and be prepared to stop","accessibilityLabel":"Horse riders on a road with traffic following at a safe distance","playbackRate":0.9,"media":{"video":"https://videos.pexels.com/video-files/8624906/8624906-hd_1920_1080_30fps.mp4","videoSources":["https://videos.pexels.com/video-files/8624906/8624906-hd_1920_1080_30fps.mp4"],"poster":"https://images.pexels.com/videos/8624906/pexels-photo-8624906.jpeg?auto=compress&dpr=1&h=750&w=1260","credit":"Pexels — RDNE Stock project","sourcePage":"https://www.pexels.com/video/man-and-woman-riding-horses-in-the-streets-8624906/"},"timeline":[{"at":0.3,"end":2.2,"event":"observe","textIt":"Ci sono cavalli davanti a te mentre ti avvicini alla rotatoria.","textEn":"There are horses ahead as you approach the roundabout."},{"at":2.3,"end":4.4,"event":"hazard","textIt":"Un cavallo può reagire improvvisamente a rumori, traffico o movimenti ravvicinati.","textEn":"A horse can react suddenly to noise, traffic or close movement."},{"at":4.5,"end":6.8,"event":"explain","textIt":"Rallenta, lascia molto spazio e tieniti pronto a fermarti.","textEn":"Slow down, leave plenty of room and be prepared to stop."},{"at":6.9,"end":10,"event":"correct","textIt":"Lascia molto spazio ai cavalli e preparati a fermarti.","textEn":"Give the horses plenty of room and be prepared to stop."}],"ui":{"staticUntilFinal":true,"useVideoFreezeFrames":false,"phaseFreezeKeys":["horsesRoomStop190_p0","horsesRoomStop190_p1","horsesRoomStop190_p2"],"hotspot":{"left":48,"top":55,"radiusX":38,"radiusY":31,"instructionIt":"TOCCA I CAVALLI","instructionEn":"TAP THE HORSES","ariaIt":"Tocca i cavalli davanti al traffico","ariaEn":"Tap the horses ahead of the traffic"},"phases":[{},{"titleIt":"CAVALLI DAVANTI","titleEn":"HORSES AHEAD","bodyIt":"Riduci la velocità e osserva attentamente i loro movimenti.","bodyEn":"Reduce speed and watch their movements carefully."},{"titleIt":"LASCIA MOLTO SPAZIO","titleEn":"LEAVE PLENTY OF ROOM","bodyIt":"Non avvicinarti: uno spazio ampio riduce pressione e rischio.","bodyEn":"Do not crowd them: generous space reduces pressure and risk."},{"titleIt":"PREPARATI A FERMARTI","titleEn":"BE PREPARED TO STOP","bodyIt":"Se il cavallo rallenta o reagisce, devi poter fermare il veicolo in sicurezza.","bodyEn":"If a horse slows or reacts, you must be able to stop safely."}],"phaseOptions":[{"startRatio":0.1,"freeze":true},{"startRatio":0.38,"freeze":true},{"startRatio":0.66,"freeze":true},{"startRatio":0.05,"autoplay":true,"endRatio":0.92}]},"coach":{"missIt":"Concentrati sullo spazio necessario attorno ai cavalli.","missEn":"Focus on the space needed around the horses.","hitIt":"Esatto: molto spazio e pronti a fermarsi.","hitEn":"Correct: plenty of room and be prepared to stop."},"learning":{"correctIt":"Avvicinandoti a una rotatoria con cavalli davanti, lascia molto spazio e preparati a fermarti.","correctEn":"When approaching a roundabout with horses ahead, give them plenty of room and be prepared to stop."}});

